import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as e,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"在 Linux 上安裝 MariaDB 或 MySQL | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝 MariaDB 或 MySQL | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝 MariaDB 或 MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝 MariaDB 或 MySQL | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20201013 Install MariaDB or MySQL on Linux","title":"在 Linux 上安裝 MariaDB 或 MySQL","tag":"202010","desc":""},"relativePath":"202010/20201013 Install MariaDB or MySQL on Linux.md","filePath":"[post].md"}'),u={name:"202010/20201013 Install MariaDB or MySQL on Linux.md"};function h(g,s,m,b,k,y){const n=p("Link");return r(),o("div",null,[s[21]||(s[21]=i("h1",{id:"在-linux-上安裝-mariadb-或-mysql",tabindex:"-1"},[a("在 Linux 上安裝 MariaDB 或 MySQL "),i("a",{class:"header-anchor",href:"#在-linux-上安裝-mariadb-或-mysql","aria-label":"Permalink to “在 Linux 上安裝 MariaDB 或 MySQL”"},"​")],-1)),s[22]||(s[22]=i("blockquote",null,[i("p",null,"開始在 Linux 系統上使用開源的 SQL 資料庫吧。")],-1)),s[23]||(s[23]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/22/144122hkkqrs2dhi9c7kif.jpg",alt:""})],-1)),i("p",null,[e(n,{href:"https://mariadb.org/"},{default:t(()=>[...s[0]||(s[0]=[a("MariaDB",-1)])]),_:1}),s[2]||(s[2]=a(" 和 ",-1)),e(n,{href:"https://www.mysql.com/"},{default:t(()=>[...s[1]||(s[1]=[a("MySQL",-1)])]),_:1}),s[3]||(s[3]=a(" 都是使用 SQL 的開源資料庫，並且共享相同的初始代碼庫。MariaDB 是 MySQL 的替代品，你可以使用相同的命令（",-1)),s[4]||(s[4]=i("code",null,"mysql",-1)),s[5]||(s[5]=a("）與 MySQL 和 MariaDB 資料庫進行交互。因此，本文同時適用於 MariaDB 和 MySQL。",-1))]),s[24]||(s[24]=d(`<h3 id="安裝-mariadb" tabindex="-1">安裝 MariaDB <a class="header-anchor" href="#安裝-mariadb" aria-label="Permalink to “安裝 MariaDB”">​</a></h3><p>你可以使用你的 Linux 發行版的包管理器安裝 MariaDB。在大多數發行版上，MariaDB 分為服務器包和客户端包。服務器包提供了資料庫“引擎”，即 MariaDB 在後台運行（通常在物理服務器上）的部分，它監聽數據輸入或數據輸出請求。客户端包提供了 <code>mysql</code> 命令，你可以用它來與服務器通信。</p><p>在 RHEL、Fedora、CentOS 或類似的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mariadb mariadb-server</span></span></code></pre></div><p>在 Debian、Ubuntu、Elementary 或類似的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install mariadb-client mariadb-server</span></span></code></pre></div><p>其他操作系統可能會以不同的打包系統封裝 MariaDB，所以你可能需要搜索你的軟件倉庫來了解你的發行版的維護者是如何提供它的。</p><h3 id="啓動-mariadb" tabindex="-1">啓動 MariaDB <a class="header-anchor" href="#啓動-mariadb" aria-label="Permalink to “啓動 MariaDB”">​</a></h3><p>因為 MariaDB 被設計為部分作為資料庫服務器，它可以在一台計算機上運行，並從另一台計算機上進行管理。只要你能訪問運行它的計算機，你就可以使用 <code>mysql</code> 命令來管理資料庫。在寫這篇文章時，我在本地計算機上運行了 MariaDB，但你同樣可與遠程系統上託管的 MariaDB 資料庫進行交互。</p><p>在啓動 MariaDB 之前，你必須創建一個初始資料庫。在初始化其文件結構時，你應該定義你希望 MariaDB 使用的用户。默認情況下，MariaDB 使用當前用户，但你可能希望它使用一個專用的用户帳户。你的包管理器可能為你配置了一個系統用户和組。使用 <code>grep</code> 查找是否有一個 <code>mysql</code> 組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep mysql /etc/group</span></span>
<span class="line"><span>mysql:x:27:</span></span></code></pre></div><p>你也可以在 <code>/etc/passwd</code> 中尋找這個專門的用户，但通常情況下，有組就會有用户。如果沒有專門的 <code>mysql</code> 用户和組，可以在 <code>/etc/group</code> 中尋找一個明顯的替代品（比如 <code>mariadb</code>）。如果沒有，請閲讀你的發行版文檔來了解 MariaDB 是如何運行的。</p><p>假設你的安裝使用 <code>mysql</code>，初始化資料庫環境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mysql_install_db --user=mysql</span></span>
<span class="line"><span>Installing MariaDB/MySQL system tables in &#39;/var/lib/mysql&#39;...</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這一步的結果顯示了接下來你必須執行的配置 MariaDB 的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PLEASE REMEMBER TO SET A PASSWORD FOR THE MariaDB root USER !</span></span>
<span class="line"><span>To do so, start the server, then issue the following commands:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&#39;/usr/bin/mysqladmin&#39; -u root password &#39;new-password&#39;</span></span>
<span class="line"><span>&#39;/usr/bin/mysqladmin&#39; -u root -h $(hostname) password &#39;new-password&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Alternatively you can run:</span></span>
<span class="line"><span>&#39;/usr/bin/mysql_secure_installation&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>which will also give you the option of removing the test</span></span>
<span class="line"><span>databases and anonymous user created by default.  This is</span></span>
<span class="line"><span>strongly recommended for production servers.</span></span></code></pre></div><p>使用你的發行版的初始化系統啓動 MariaDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start mariadb</span></span></code></pre></div><p>在啓動時啓用 MariaDB 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now mariadb</span></span></code></pre></div><p>現在你已經有了一個 MariaDB 服務器，為它設置一個密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysqladmin -u root password &#39;myreallysecurepassphrase&#39;</span></span>
<span class="line"><span>mysqladmin -u root -h $(hostname) password &#39;myreallysecurepassphrase&#39;</span></span></code></pre></div><p>最後，如果你打算在生產服務器上使用它，請在上線前運行 <code>mysql_secure_installation</code> 命令。</p><hr>`,24)),i("p",null,[s[7]||(s[7]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/10/mariadb-mysql-linux"},{default:t(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/20/10/mariadb-mysql-linux",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[8]||(s[8]=[a("Seth Kenlon",-1)])]),_:1}),s[13]||(s[13]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[10]||(s[10]=[a("geekpi",-1)])]),_:1}),s[15]||(s[15]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[a("Linux中國",-1)])]),_:1}),s[20]||(s[20]=a(" 榮譽推出",-1))])])}const D=l(u,[["render",h]]);export{M as __pageData,D as default};
